import React, { useState } from "react";
import { Link } from "react-router-dom";
import "../App.css";

const Navbar = () => {
  const [showTransaction, setShowTransaction] = useState(false);
  const [showAdmin, setShowAdmin] = useState(false);

  const toggleTransaction = () => {
    setShowTransaction(!showTransaction);
    setShowAdmin(false); // close other menu
  };

  const toggleAdmin = () => {
    setShowAdmin(!showAdmin);
    setShowTransaction(false); // close other menu
  };

  const closeMenus = () => {
    setShowTransaction(false);
    setShowAdmin(false);
  };

  return (
    <header className="navbar" onClick={closeMenus}>
      <h1>ReGym</h1>
      <nav onClick={(e) => e.stopPropagation()}>
        <Link to="/" className="nav-link">Home</Link>
        <Link to="/login" className="nav-link">Login</Link>
        <Link to="/register" className="nav-link">Register</Link>
        <Link to="/dashboard" className="nav-link">Dashboard</Link>

        {/* Transaction Dropdown */}
        <div className="dropdown">
          <span className="nav-link dropdown-toggle" onClick={toggleTransaction}>
            Transaction ▾
          </span>
          {showTransaction && (
            <div className="dropdown-menu">
              <Link to="/favorites" className="dropdown-item">Favorites</Link>
              <Link to="/my-sales" className="dropdown-item">My Sales</Link>
              <Link to="/rate-user" className="dropdown-item">Rate User</Link>
            </div>
          )}
        </div>

        {/* Admin Dropdown */}
        <div className="dropdown">
          <span className="nav-link dropdown-toggle" onClick={toggleAdmin}>
            Admin ▾
          </span>
          {showAdmin && (
            <div className="dropdown-menu">
              
              <Link to="/admin/users" className="dropdown-item">Users</Link>
              <Link to="/admin/reports" className="dropdown-item">Reports</Link>
              <Link to="/admin/flagged" className="dropdown-item">Flagged Listings</Link>
            </div>
          )}
        </div>
      </nav>
    </header>
  );
};

export default Navbar;
